s="_YRW IY_X I_R_ IYRZ".replace(' ','')
opts={'A':'XRYY','B':'IRZY','C':'IYYX','D':'IRYY'}
def fill(o):
    it=iter(o);t=''.join(next(it) if c=='_' else c for c in s)
    return t
def ok(t):
    b=[t[i:i+4] for i in range(0,16,4)]
    return len({x[0] for x in b})==1 and len({x[1] for x in b})==1 and len({x[2] for x in b})==1 and [x[3] for x in b]==list('WXYZ')
res=[k for k,v in opts.items() if ok(fill(v))]
assert res==['D']
assert opts['D']=='IRYY'

s=[({'cat','dog','monkey'},{55,66,88}),({'camel','cat','donkey'},{66,99,33}),({'dog','goat','tiger'},{88,11,22})]
code={}
for w in ['cat','dog','monkey']:
    sets=[c for ws,c in s if w in ws]
    r=set.intersection(*sets)
    if len(sets)>1: code[w]=r.pop()
code['monkey']=({55,66,88}-{code['cat'],code['dog']}).pop()
opts={'A':88,'B':66,'C':11,'D':55}
assert code['monkey']==opts['D']
for k in 'ABC': assert code['monkey']!=opts[k]

