def ev(n):
    a,b,c,d,e,f,g,h,i=n
    return a*b+c/d+e+f*g-h/i
base=[6,3,8,2,21,5,4,14,7]
def sw(x,y):
    n=base[:];ix=[i for i,v in enumerate(n) if v in (x,y)]
    n[ix[0]],n[ix[1]]=n[ix[1]],n[ix[0]];return ev(n)
opts={'A':(8,4),'B':(3,5),'C':(21,14),'D':(2,4)}
res=[k for k,(x,y) in opts.items() if sw(x,y)==53]
assert res==['C']

